  rankdir=LR;
  bgcolor="transparent";
  node [shape=box, style="rounded,filled", fontname="Helvetica", fontsize=16, fillcolor="#4a4a4a", fontcolor="white", color="#00000000", penwidth=1.5];
  edge [arrowsize=0.8, color="#9e9e9e", penwidth=1.4];

  "attract"  [label="Attract mode"];
  "playing"  [label="Playing"];
